// All the database / business logic that does NOT talk to Stripe lives here.
// Students do not edit this file - it is provided in the starter as-is.
import { prisma } from './db.js';

const include = { items: { include: { product: true } } };

class HttpError extends Error {
  constructor(status, message) {
    super(message);
    this.status = status;
  }
}
export { HttpError };

// Turns [{ productId, quantity }] from the browser into trusted lines + total.
// Prices ALWAYS come from our database, never from the client.
export async function validateCart(items) {
  if (!Array.isArray(items) || items.length === 0) throw new HttpError(400, 'Cart is empty');

  const products = await prisma.product.findMany({
    where: { id: { in: items.map((i) => i.productId) } },
  });

  const lines = items.map((item) => {
    const product = products.find((p) => p.id === item.productId);
    const quantity = Number(item.quantity);
    if (!product || !Number.isInteger(quantity) || quantity < 1) throw new HttpError(400, 'Invalid item');
    if (product.stock < quantity) throw new HttpError(409, `Not enough stock for ${product.name}`);
    return { product, quantity };
  });

  const totalCents = lines.reduce((sum, l) => sum + l.product.priceCents * l.quantity, 0);
  return { lines, totalCents };
}

// Saved BEFORE the customer goes to Stripe, so we always have a record.
export function createPendingOrder(lines, totalCents) {
  return prisma.order.create({
    data: {
      totalCents,
      items: {
        create: lines.map((l) => ({
          productId: l.product.id,
          quantity: l.quantity,
          unitPriceCents: l.product.priceCents, // price snapshot
        })),
      },
    },
  });
}

export function attachSession(orderId, stripeSessionId) {
  return prisma.order.update({ where: { id: orderId }, data: { stripeSessionId } });
}

// PENDING -> PAID. Idempotent: Stripe may deliver the same event twice.
export async function markOrderPaid(orderId, { email, paymentIntentId }) {
  const order = await prisma.order.findUnique({ where: { id: orderId }, include: { items: true } });
  if (!order || order.status === 'PAID') return;

  await prisma.$transaction([
    prisma.order.update({
      where: { id: orderId },
      data: { status: 'PAID', customerEmail: email, paymentIntentId },
    }),
    ...order.items.map((i) =>
      prisma.product.update({ where: { id: i.productId }, data: { stock: { decrement: i.quantity } } })
    ),
  ]);
  console.log(`Order ${orderId} marked PAID`);
}

export function markOrderExpired(orderId) {
  return prisma.order.updateMany({ where: { id: orderId, status: 'PENDING' }, data: { status: 'EXPIRED' } });
}

export const listOrders = () => prisma.order.findMany({ include, orderBy: { id: 'desc' } });
export const findOrderBySession = (sessionId) =>
  prisma.order.findUnique({ where: { stripeSessionId: sessionId }, include });
export const findOrder = (id) => prisma.order.findUnique({ where: { id } });
export const markOrderRefunded = (id) =>
  prisma.order.update({ where: { id }, data: { status: 'REFUNDED' }, include });
